lower_bound倾向于找左边的元素，所以只有nums[mid] < target时才移动左指针；而upper_bound倾向于找右边的元素，所以当nums[mid] <= target就向右移动左指针了。 lower_bound返回的是开始的第一个满足条件的位置，而upper_bound返回的是第一个不满足条件的位置。所以，当两个相等的时候代表没有找到，如果找到了的话，需要返回的是[left, right - 1]。 class Solution {
public: int lower_bound(vector<int>& nums, int target) { int left = 0; int right = nums.size(); while(left < right){ int mid = (right + left) / 2; if(nums[mid] < target){ left = mid + 1; }else{ right = mid; } } return left; } int upper_bound(vector<int>& nums, int target){ int left = 0; int right = nums.size(); while(left < right){ int mid = (right + left) / 2; if(nums[mid] <= target){ left = mid + 1; }else { right = mid; } } return left; } vector<int> searchRange(vector<int>& nums, int target) { int leftBorder = lower_bound(nums, target); int rightBorder = upper_bound(nums, target); if (leftBorder == rightBorder) return {-1, -1}; else return {leftBorder, rightBorder - 1}; }
};

